final class yaca_context_s extends ffi.Opaque {}

final class yaca_key_s extends ffi.Opaque {}

/// @brief Enumeration for formats YACA key.
/// @since_tizen 3.0
abstract class yaca_key_format_e {
  /// Key is either PKCS#1 for RSA or SSLeay for DSA, also use this option for symmetric
  static const int YACA_KEY_FORMAT_DEFAULT = 0;

  /// Key is in PKCS#8, can only be used for asymmetric private keys
  static const int YACA_KEY_FORMAT_PKCS8 = 1;
}

/// @brief Enumeration for formats YACA key file.
/// @since_tizen 3.0
abstract class yaca_key_file_format_e {
  /// Key file is in raw binary format, used for symmetric keys
  static const int YACA_KEY_FILE_FORMAT_RAW = 0;

  /// Key file is encoded in ASCII-base64, used for symmetric keys
  static const int YACA_KEY_FILE_FORMAT_BASE64 = 1;

  /// Key file is in PEM file format, used for asymmetric keys
  static const int YACA_KEY_FILE_FORMAT_PEM = 2;

  /// Key file is in DER file format, used for asymmetric keys
  static const int YACA_KEY_FILE_FORMAT_DER = 3;
}

/// @brief Enumeration for YACA key types, Initialization Vector is considered as key.
/// @since_tizen 3.0
abstract class yaca_key_type_e {
  /// Generic symmetric cipher KEY
  static const int YACA_KEY_TYPE_SYMMETRIC = 0;

  /// DES* key - must be handled differently because of parity bits
  static const int YACA_KEY_TYPE_DES = 1;

  /// Initialization Vector for symmetric algorithms
  static const int YACA_KEY_TYPE_IV = 2;

  /// RSA public key
  static const int YACA_KEY_TYPE_RSA_PUB = 3;

  /// RSA private key
  static const int YACA_KEY_TYPE_RSA_PRIV = 4;

  /// Digital Signature Algorithm public key
  static const int YACA_KEY_TYPE_DSA_PUB = 5;

  /// Digital Signature Algorithm private key
  static const int YACA_KEY_TYPE_DSA_PRIV = 6;

  /// Diffie-Hellman public key
  static const int YACA_KEY_TYPE_DH_PUB = 7;

  /// Diffie-Hellman private key
  static const int YACA_KEY_TYPE_DH_PRIV = 8;

  /// Elliptic Curve public key (for DSA and DH)
  static const int YACA_KEY_TYPE_EC_PUB = 9;

  /// Elliptic Curve private key (for DSA and DH)
  static const int YACA_KEY_TYPE_EC_PRIV = 10;

  /// Digital Signature Algorithm parameters
  static const int YACA_KEY_TYPE_DSA_PARAMS = 11;

  /// Diffie-Hellman parameters
  static const int YACA_KEY_TYPE_DH_PARAMS = 12;

  /// Elliptic Curve parameters
  static const int YACA_KEY_TYPE_EC_PARAMS = 13;
}

/// @brief Enumeration for YACA key lengths.
/// It is possible to use arbitrary integer instead,
/// this enum values are placed here to avoid magic numbers.
/// @since_tizen 3.0
abstract class yaca_key_bit_length_e {
  /// 64 bits
  static const int YACA_KEY_LENGTH_IV_64BIT = 64;

  /// 128 bits
  static const int YACA_KEY_LENGTH_IV_128BIT = 128;

  /// 8 bits
  static const int YACA_KEY_LENGTH_UNSAFE_8BIT = 8;

  /// 40 bits
  static const int YACA_KEY_LENGTH_UNSAFE_40BIT = 40;

  /// 64 bits
  static const int YACA_KEY_LENGTH_UNSAFE_64BIT = 64;

  /// 80 bits
  static const int YACA_KEY_LENGTH_UNSAFE_80BIT = 80;

  /// 128 bits
  static const int YACA_KEY_LENGTH_UNSAFE_128BIT = 128;

  /// 192 bits
  static const int YACA_KEY_LENGTH_192BIT = 192;

  /// 256 bits
  static const int YACA_KEY_LENGTH_256BIT = 256;

  /// 512 bits
  static const int YACA_KEY_LENGTH_512BIT = 512;

  /// 1024 bits
  static const int YACA_KEY_LENGTH_1024BIT = 1024;

  /// 2048 bits
  static const int YACA_KEY_LENGTH_2048BIT = 2048;

  /// 3072 bits
  static const int YACA_KEY_LENGTH_3072BIT = 3072;

  /// 4096 bits
  static const int YACA_KEY_LENGTH_4096BIT = 4096;
}

/// @brief Enumeration for YACA elliptic curve types with their bit lengths.
/// It's meant to be passed or returned as a @a key_bit_len param
/// in appropriate functions when dealing with elliptic curves.
/// @since_tizen 3.0
abstract class yaca_key_bit_length_ec_e {
  /// Elliptic curve prime192v1
  static const int YACA_KEY_LENGTH_EC_PRIME192V1 = 805306560;

  /// Elliptic curve prime256v1
  static const int YACA_KEY_LENGTH_EC_PRIME256V1 = 805306624;

  /// Elliptic curve secp256k1
  static const int YACA_KEY_LENGTH_EC_SECP256K1 = 824180992;

  /// Elliptic curve secp384r1
  static const int YACA_KEY_LENGTH_EC_SECP384R1 = 823132544;

  /// Elliptic curve secp521r1
  static const int YACA_KEY_LENGTH_EC_SECP521R1 = 823132681;
}

/// @brief Enumeration for YACA DH parameters taken from RFC 5114.
/// It's meant to be passed or returned as a @a key_bit_len param
/// in appropriate functions when dealing with DH and wanting to
/// use RFC 5114 values.
/// @since_tizen 3.0
abstract class yaca_key_bit_length_dh_rfc_e {
